CREATE DATABASE practica_equipos_ligas;

CREATE TABLE "Teams" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "Name" VARCHAR(50) NOT NULL,
    "Country" VARCHAR(50) NOT NULL,
    "PlayersQuantity" INTEGER NOT NULL,
    "Enabled" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "PK_Teams" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Teams_Name" CHECK (
        char_length(trim("Name")) >= 2
    ),
    CONSTRAINT "CK_Teams_Country" CHECK (
        char_length(trim("Country")) >= 2
    ),
    CONSTRAINT "CK_Teams_PlayersQuantity" CHECK (
        "PlayersQuantity" BETWEEN 11 AND 22
    )
);

CREATE TABLE "Leagues" (
    Id INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "Name" VARCHAR(50) NOT NULL,
    "Country" VARCHAR(50) NOT NULL,
    "StartDate" DATE NOT NULL DEFAULT CURRENT_DATE,
    "EndDate" DATE NOT NULL DEFAULT CURRENT_DATE,
    "Enabled" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "PK_Leagues" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Leagues_Name" CHECK (
        char_length(trim("Name")) >= 2
    ),
    CONSTRAINT "CK_Leagues_Country" CHECK (
        char_length(trim("Country")) >= 2
    ),
    CONSTRAINT "CK_Leagues_Dates" CHECK ("StartDate" <= "EndDate")
);

CREATE TABLE "LeagueTeams" (
    "LeagueId" INTEGER NOT NULL,
    "TeamId" INTEGER NOT NULL,
    CONSTRAINT "PK_LeagueTeams" PRIMARY KEY ("LeagueId", "TeamId"),
    CONSTRAINT "FK_LeagueTeams_Leagues_LeagueId" FOREIGN KEY ("LeagueId") REFERENCES "Leagues" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_LeagueTeams_Teams_TeamId" FOREIGN KEY ("TeamId") REFERENCES "Teams" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_LeagueTeams_TeamId" ON "LeagueTeams" ("TeamId");